function ChannelsNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.channels.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/channels/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New channel" actions={<Link href="/channels" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <ChannelsForm
        fields={CHANNELS_CREATE}
        initial={EMPTY_CHANNELS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toChannelsCreateInput(values))}
      />
    </Pane>
  );
}

function ChannelsDetailInner() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.channels.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["channels"]["update"]) => client.channels.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["channels"]["delete"]) => client.channels.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/channels");
    }
  });
  const joinAction = useMutation({
    mutationFn: (input: Inputs["channels"]["join"]) => client.channels.join(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "Channel " + text(row.id)}
      actions={
        <>
          <Link href="/channels" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canJoin(user, row) ? (
            <Button variant="outline" size="sm" disabled={joinAction.isPending} onClick={() => joinAction.mutate({ id })}>
              Join
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this channel?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={joinAction.error} className="mb-4" />
      {editing ? (
        <ChannelsForm
          fields={CHANNELS_UPDATE}
          initial={channelsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toChannelsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Team">{text(row.team_id) || "—"}</FieldRow>
        <FieldRow label="Created By">{text(row.created_by) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Private">{row.private == null ? "—" : <Badge variant={row.private ? "default" : "outline"}>{yesNo(row.private)}</Badge>}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Members">
          {row.members.length === 0 ? (
            "—"
          ) : (
            <ul className="space-y-1">
              {row.members.map(item => (
                <li key={text(item.id)}>{text(item.id)}</li>
              ))}
            </ul>
          )}
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}

